                      placeholder=&quot;90210&quot;
                    /&gt;
                  &lt;/div&gt;
                &lt;/div&gt;
              &lt;/div&gt;
            &lt;/section&gt;

            {/* Building Info */}
            {(quoteType === 'property' || quoteType === 'package') &amp;&amp; (
