import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

export default defineConfig({
  plugins: [tailwindcss(), react()], 
})

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import type { Quote } from '../types';

const Dashboard = () => {
  const [quotes, setQuotes] = useState&lt;Quote[]&gt;([]);
  const navigate = useNavigate();

  useEffect(() =&gt; {
    const stored = localStorage.getItem('quotes');
    if (stored) {
      setQuotes(JSON.parse(stored));
    }
  }, []);

  const handleNewQuote = () =&gt; {
    navigate('/quote/new');
  };

  const handleEditQuote = (id: string) =&gt; {
    navigate(`/quote/${id}`);
  };

  return (
    &lt;&gt;
      &lt;header className=&quot;bg-white shadow-sm border-b border-gray-200&quot;&gt;
        &lt;div className=&quot;max-w-7xl mx-auto px-4 sm:px-6 lg:px-8&quot;&gt;
          &lt;div className=&quot;flex justify-between items-center py-6 md:py-8&quot;&gt;
            &lt;div&gt;
              &lt;h1 className=&quot;text-3xl md:text-4xl font-bold text-gray-900&quot;&gt;MGA Quote Dashboard&lt;/h1&gt;
              &lt;p className=&quot;text-lg text-gray-600 mt-1&quot;&gt;Manage your commercial insurance quotes&lt;/p&gt;
            &lt;/div&gt;
            &lt;button
              onClick={handleNewQuote}
              className=&quot;bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white font-bold py-3 px-6 rounded-xl shadow-lg focus:outline-none focus:ring-4 focus:ring-indigo-200 transition-all text-lg&quot;
            &gt;
              + New Quote
            &lt;/button&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/header&gt;

      &lt;main className=&quot;max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12&quot;&gt;
        {quotes.length === 0 ? (
          &lt;div className=&quot;text-center py-24&quot;&gt;
            &lt;div className=&quot;mx-auto h-24 w-24 bg-gray-200 rounded-2xl flex items-center justify-center mb-6&quot;&gt;
              &lt;span className=&quot;text-3xl&quot;&gt;📋&lt;/span&gt;
            &lt;/div&gt;
            &lt;h2 className=&quot;text-2xl font-bold text-gray-900 mb-4&quot;&gt;No quotes yet&lt;/h2&gt;
            &lt;p className=&quot;text-lg text-gray-600 mb-8&quot;&gt;Get started by creating your first commercial property or GL quote.&lt;/p&gt;
            &lt;button
              onClick={handleNewQuote}
              className=&quot;bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white font-bold py-3 px-8 rounded-xl shadow-lg focus:outline-none focus:ring-4 focus:ring-indigo-200 transition-all&quot;
            &gt;
              Create First Quote
            &lt;/button&gt;
          &lt;/div&gt;
        ) : (
          &lt;&gt;
            &lt;div className=&quot;mb-8&quot;&gt;
              &lt;h2 className=&quot;text-2xl font-bold text-gray-900&quot;&gt;Recent Quotes ({quotes.length})&lt;/h2&gt;
            &lt;/div&gt;
            &lt;div className=&quot;bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden&quot;&gt;
              &lt;table className=&quot;min-w-full divide-y divide-gray-200&quot;&gt;
                &lt;thead className=&quot;bg-gray-50&quot;&gt;
                  &lt;tr&gt;
                    &lt;th className=&quot;px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider&quot;&gt;Quote ID&lt;/th&gt;
                    &lt;th className=&quot;px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider&quot;&gt;Type&lt;/th&gt;
                    &lt;th className=&quot;px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider&quot;&gt;Insured&lt;/th&gt;
                    &lt;th className=&quot;px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider&quot;&gt;Total Premium&lt;/th&gt;
                    &lt;th className=&quot;px-6 py-4 text-left text-xs font-bold text-gray-500 uppercase tracking-wider&quot;&gt;Created&lt;/th&gt;
                  &lt;/tr&gt;
                &lt;/thead&gt;
                &lt;tbody className=&quot;bg-white divide-y divide-gray-200&quot;&gt;
                  {quotes.map((quote) =&gt; (
                    &lt;tr 
                      key={quote.id}
                      onClick={() =&gt; handleEditQuote(quote.id)}
                      className=&quot;hover:bg-gray-50 cursor-pointer transition-colors h-16&quot;
                    &gt;
                      &lt;td className=&quot;px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900&quot;&gt;{quote.id.slice(0,8)}&lt;/td&gt;
                      &lt;td className=&quot;px-6 py-4 whitespace-nowrap&quot;&gt;
                        &lt;span className={`px-3 py-1 rounded-full text-xs font-bold ${
                          quote.type === 'property' ? 'bg-green-100 text-green-800' :
                          quote.type === 'gl' ? 'bg-blue-100 text-blue-800' :
                          'bg-purple-100 text-purple-800'
                        }`}&gt;{
                          quote.type.charAt(0).toUpperCase() + quote.type.slice(1)
                        }&lt;/span&gt;
                      &lt;/td&gt;
                      &lt;td className=&quot;px-6 py-4 text-sm text-gray-900&quot;&gt;{quote.insured.name}&lt;/td&gt;
                      &lt;td className=&quot;px-6 py-4 whitespace-nowrap text-sm font-bold text-gray-900&quot;&gt;${quote.totalPremium.toLocaleString()}&lt;/td&gt;
                      &lt;td className=&quot;px-6 py-4 whitespace-nowrap text-sm text-gray-500&quot;&gt;{new Date(quote.createdDate).toLocaleDateString()}&lt;/td&gt;
                    &lt;/tr&gt;
                  ))}
                &lt;/tbody&gt;
              &lt;/table&gt;
            &lt;/div&gt;
          &lt;/&gt;
        )}
      &lt;/main&gt;
    &lt;/&gt;
  );
};

export default Dashboard;

import { useState, useEffect, useCallback } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { v4 as uuidv4 } from 'uuid';
import jsPDF from 'jspdf';
import type { Quote, QuoteType, Insured, BuildingInfo, LiabilityInfo, ClaimsInfo, QuotePreview } from '../types';

const QuoteForm = () => {
  const { quoteId } = useParams&lt;{ quoteId?: string }&gt;();
  const navigate = useNavigate();
  const isNew = !quoteId || quoteId === 'new';

  const [quoteType, setQuoteType] = useState&lt;QuoteType&gt;('property');
  const [insured, setInsured] = useState&lt;Insured&gt;({ name: '', address: '', city: '', state: '', zip: '' });
  const [building, setBuilding] = useState&lt;BuildingInfo&gt;({ sqFt: 0, yearBuilt: 0, construction: 'frame', tivBuilding: 0, tivContents: 0, deductible: '1k' });
  const [liability, setLiability] = useState&lt;LiabilityInfo&gt;({ grossReceipts: 0, limits: '1m/2m' });
  const [claims, setClaims] = useState&lt;ClaimsInfo&gt;({ priorClaimsLast5Yrs: 0 });
  const [preview, setPreview] = useState&lt;QuotePreview&gt;({ propertyPremium: 0, glPremium: 0, totalPremium: 0 });

  // Load existing quote
  useEffect(() =&gt; {
    if (!isNew) {
      try {
        const quotes: Quote[] = JSON.parse(localStorage.getItem('quotes') || '[]');
        const quote = quotes.find((q) =&gt; q.id === quoteId);
        if (quote) {
          setQuoteType(quote.type);
          setInsured(quote.insured);
          if (quote.building) setBuilding(quote.building);
          if (quote.liability) setLiability(quote.liability);
          setClaims(quote.claims);
          setPreview({
            propertyPremium: quote.propertyPremium,
            glPremium: quote.glPremium,
            totalPremium: quote.totalPremium,
          });
        }
      } catch (e) {
        console.error('Failed to load quote', e);
      }
    }
  }, [quoteId, isNew]);

  const calculatePreview = useCallback(() =&gt; {
    let propertyPremium = 0;
    let glPremium = 0;

    // Property calculation
    if (quoteType === 'property' || quoteType === 'package') {
      const baseRate = 0.001; // $1 per $1k TIV
      const constructionAdj = building.construction === 'frame' ? 1.2 : building.construction === 'brick' ? 1.0 : 0.8;
      const deductibleAdj = building.deductible === '1k' ? 1.0 : building.deductible === '2.5k' ? 0.95 : 0.9;
      const ageAdj = Math.max(0.8, 1 - (new Date().getFullYear() - building.yearBuilt) * 0.01);
      const tiv = building.tivBuilding + building.tivContents;
      propertyPremium = tiv * baseRate * constructionAdj * deductibleAdj * ageAdj + building.sqFt * 0.05;
    }

    // GL calculation
    if (quoteType === 'gl' || quoteType === 'package') {
      const baseRate = 0.0005;
      const limitMult = liability.limits === '100k/300k' ? 1.0 : liability.limits === '1m/2m' ? 1.5 : 2.0;
      const claimAdj = 1 + claims.priorClaimsLast5Yrs * 0.25;
      glPremium = liability.grossReceipts * baseRate * limitMult * claimAdj;
    }

    const totalPremium = propertyPremium + glPremium;
    return {
      propertyPremium: Math.round(propertyPremium),
      glPremium: Math.round(glPremium),
      totalPremium: Math.round(totalPremium),
    };
  }, [quoteType, building, liability, claims]);

  // Update preview and save active submission
  useEffect(() =&gt; {
    const newPreview = calculatePreview();
    setPreview(newPreview);
    // Save active submission for extension
    const activeSubmission = {
      type: quoteType,
      insured,
      building: quoteType !== 'gl' ? building : undefined,
      liability: quoteType !== 'property' ? liability : undefined,
      claims,
      preview: newPreview,
    };
    localStorage.setItem('mga-active-submission', JSON.stringify(activeSubmission));
  }, [calculatePreview, quoteType, insured, building, liability, claims]);

  const saveDraft = () =&gt; {
    const fullQuote: Quote = {
      id: isNew ? uuidv4() : quoteId!,
      type: quoteType,
      insured,
      building: quoteType !== 'gl' ? building : undefined,
      liability: quoteType !== 'property' ? liability : undefined,
      claims,
      ...preview,
      createdDate: isNew ? new Date().toISOString() : (JSON.parse(localStorage.getItem('quotes') || '[]') as Quote[]).find(q =&gt; q.id === quoteId!)?.createdDate || new Date().toISOString(),
      updatedDate: new Date().toISOString(),
    };

    try {
      const quotes: Quote[] = JSON.parse(localStorage.getItem('quotes') || '[]');
      const index = quotes.findIndex((q) =&gt; q.id === fullQuote.id);
      if (index &gt;= 0) {
        quotes[index] = fullQuote;
      } else {
        quotes.push(fullQuote);
      }
      localStorage.setItem('quotes', JSON.stringify(quotes));
      alert('Quote saved as draft!');
      navigate('/');
    } catch (e) {
      alert('Failed to save draft');&n    }
  };

  const generatePDF = () =&gt; {
    const doc = new jsPDF();
    let y = 20;

    doc.setFontSize(20);
    doc.text('Commercial Insurance Quote', 105, y, { align: 'center' });
    y += 15;
    doc.setFontSize(12);
    doc.text(`Quote ID: ${isNew ? 'NEW' : quoteId?.slice(0,8) || 'N/A'}`, 20, y);
    y += 10;
    doc.text(`Type: ${quoteType.toUpperCase()}`, 20, y);
    y += 10;

    // Insured
    doc.text('Insured Details:', 20, y);
    y += 8;
    doc.text(`Name: ${insured.name}`, 20, y); y += 6;
    doc.text(`Address: ${insured.address}`, 20, y); y += 6;
    doc.text(`${insured.city}, ${insured.state} ${insured.zip}`, 20, y); y += 15;

    // Building if applicable
    if (quoteType !== 'gl') {
      doc.text('Building Information:', 20, y);
      y += 8;
      doc.text(`Square Footage: ${building.sqFt.toLocaleString()} sq ft`, 20, y); y += 6;
      doc.text(`Year Built: ${building.yearBuilt}`, 20, y); y += 6;
      doc.text(`Construction: ${building.construction}`, 20, y); y += 6;
      doc.text(`TIV Building: $${building.tivBuilding.toLocaleString()}`, 20, y); y += 6;
      doc.text(`TIV Contents: $${building.tivContents.toLocaleString()}`, 20, y); y += 6;
      doc.text(`Deductible: $${building.deductible.replace('k','000')}`, 20, y); y += 15;
    }

    // Liability if applicable
    if (quoteType !== 'property') {
      doc.text('Liability Information:', 20, y);
      y += 8;
      doc.text(`Gross Receipts: $${liability.grossReceipts.toLocaleString()}`, 20, y); y += 6;
      doc.text(`Limits: ${liability.limits}`, 20, y); y += 15;
    }

    // Claims
    doc.text('Claims History:', 20, y);
    y += 8;
    doc.text(`Prior Claims (last 5 yrs): ${claims.priorClaimsLast5Yrs}`, 20, y); y += 15;

    // Premiums
    doc.setFontSize(14);
    doc.text('Premium Breakdown:', 20, y);
    y += 10;
    doc.setFontSize(12);
    if (preview.propertyPremium &gt; 0) {
      doc.text(`Property: $${preview.propertyPremium.toLocaleString()}`, 30, y); y += 8;
    }
    if (preview.glPremium &gt; 0) {
      doc.text(`GL: $${preview.glPremium.toLocaleString()}`, 30, y); y += 8;
    }
    doc.setFontSize(18);
    doc.text(`TOTAL: $${preview.totalPremium.toLocaleString()}`, 20, y, { fillColor: '#000' });

    const filename = `quote-${isNew ? 'new' : quoteId || 'draft'}-${new Date().toISOString().slice(0,10)}.pdf`;
    doc.save(filename);
  };

  const updateInsured = (field: keyof Insured, value: string) =&gt; {
    setInsured({ ...insured, [field]: value });
  };

  const updateBuilding = (field: keyof BuildingInfo, value: BuildingInfo[keyof BuildingInfo]) =&gt; {
    setBuilding({ ...building, [field]: value });
  };

  const updateLiability = (field: keyof LiabilityInfo, value: LiabilityInfo[keyof LiabilityInfo]) =&gt; {
    setLiability({ ...liability, [field]: value });
  };

  const updateClaims = (field: keyof ClaimsInfo, value: number) =&gt; {
    setClaims({ ...claims, [field]: value });
  };

  return (
    &lt;&gt;
      &lt;header className=&quot;bg-white shadow-sm border-b border-gray-200 sticky top-0 z-50&quot;&gt;
        &lt;div className=&quot;max-w-7xl mx-auto px-4 sm:px-6 lg:px-8&quot;&gt;
          &lt;div className=&quot;flex justify-between items-center py-4&quot;&gt;
            &lt;div className=&quot;flex items-center space-x-4&quot;&gt;
              &lt;button 
                onClick={() =&gt; navigate('/')}
                className=&quot;flex items-center space-x-2 text-gray-500 hover:text-gray-900 font-medium&quot;
              &gt;
                &lt;span&gt;&amp;lt;-&lt;/span&gt;
                &lt;span&gt;Dashboard&lt;/span&gt;
              &lt;/button&gt;
            &lt;/div&gt;
            &lt;h1 className=&quot;text-2xl font-bold text-gray-900&quot;&gt;{
              isNew ? 'New Quote' : `Edit Quote ${quoteId?.slice(0,8)}`
            }&lt;/h1&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/header&gt;

      &lt;div className=&quot;max-w-7xl mx-auto px-4 py-8 sm:px-6 lg:px-8&quot;&gt;
        &lt;div className=&quot;grid lg:grid-cols-3 gap-8&quot;&gt;
          &lt;div className=&quot;lg:col-span-2 space-y-8&quot;&gt;
            {/* Type Tabs */}
            &lt;div&gt;
              &lt;h2 className=&quot;text-2xl font-bold text-gray-900 mb-4&quot;&gt;Coverage Type&lt;/h2&gt;
              &lt;div className=&quot;flex space-x-3 bg-white p-1 rounded-xl border&quot;&gt;
                {(['property', 'gl', 'package'] as QuoteType[]).map((type) =&gt; (
                  &lt;button
                    key={type}
                    onClick={() =&gt; setQuoteType(type)}
                    className={`flex-1 py-3 px-4 rounded-lg font-semibold transition-all ${
                      quoteType === type
                        ? 'bg-gradient-to-r from-indigo-500 to-purple-600 text-white shadow-lg'
                        : 'text-gray-600 hover:text-gray-900 hover:bg-gray-100'
                    }`}
                  &gt;
                    {type.charAt(0).toUpperCase() + type.slice(1).replace(/([A-Z])/g, ' $1')}
                  &lt;/button&gt;
                ))}
              &lt;/div&gt;
            &lt;/div&gt;

            {/* Insured Details */}
            &lt;section&gt;
              &lt;h3 className=&quot;text-xl font-bold text-gray-900 mb-6&quot;&gt;Insured Details&lt;/h3&gt;
              &lt;div className=&quot;grid md:grid-cols-2 gap-6&quot;&gt;
                &lt;div&gt;
                  &lt;label className=&quot;block text-sm font-semibold text-gray-700 mb-2&quot;&gt;Insured Name&lt;/label&gt;
                  &lt;input
