                    &lt;label className=&quot;block text-sm font-semibold text-gray-700 mb-2&quot;&gt;TIV - Building&lt;/label&gt;
                    &lt;input
                      type=&quot;number&quot;
                      value={building.tivBuilding}
                      onChange={(e) =&gt; updateBuilding('tivBuilding', parseInt(e.target.value) || 0)}
                      className=&quot;w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-4 focus:ring-green-100 focus:border-green-500 transition&quot;
                      placeholder=&quot;1000000&quot;
                    /&gt;
                  &lt;/div&gt;
