            )}

            {/* Liability Info */}
            {(quoteType === 'gl' || quoteType === 'package') &amp;&amp; (
              &lt;section&gt;
                &lt;h3 className=&quot;text-xl font-bold text-gray-900 mb-6&quot;&gt;General Liability&lt;/h3&gt;
                &lt;div className=&quot;grid md:grid-cols-2 gap-6&quot;&gt;
                  &lt;div&gt;
                    &lt;label className=&quot;block text-sm font-semibold text-gray-700 mb-2&quot;&gt;Gross Receipts ($)&lt;/label&gt;
                    &lt;input
                      type=&quot;number&quot;
                      value={liability.grossReceipts}
                      onChange={(e) =&gt; updateLiability('grossReceipts', parseInt(e.target.value) || 0)}
                      className=&quot;w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-100 focus:border-blue-500 transition&quot;
                      placeholder=&quot;1000000&quot;
                    /&gt;
                  &lt;/div&gt;
                  &lt;div&gt;
                    &lt;label className=&quot;block text-sm font-semibold text-gray-700 mb-2&quot;&gt;Occurrence Limits&lt;/label&gt;
                    &lt;select
                      value={liability.limits}
                      onChange={(e) =&gt; updateLiability('limits', e.target.value as any)}
                      className=&quot;w-full px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-4 focus:ring-blue-100 focus:border-blue-500 transition&quot;
                    &gt;
                      &lt;option value=&quot;100k/300k&quot;&gt;$100k/$300k&lt;/option&gt;
                      &lt;option value=&quot;1m/2m&quot;&gt;$1M/$2M&lt;/option&gt;
                      &lt;option value=&quot;2m/4m&quot;&gt;$2M/$4M&lt;/option&gt;
                    &lt;/select&gt;
                  &lt;/div&gt;
                &lt;/div&gt;
              &lt;/section&gt;
            )}

            {/* Claims */}
            &lt;section&gt;
              &lt;h3 className=&quot;text-xl font-bold text-gray-900 mb-6&quot;&gt;Prior Claims (Last 5 Years)&lt;/h3&gt;
              &lt;div&gt;
                &lt;label className=&quot;block text-sm font-semibold text-gray-700 mb-2&quot;&gt;Number of Claims&lt;/label&gt;
                &lt;input
                  type=&quot;number&quot;
                  min=&quot;0&quot;
                  value={claims.priorClaimsLast5Yrs}
                  onChange={(e) =&gt; updateClaims('priorClaimsLast5Yrs', parseInt(e.target.value) || 0)}
                  className=&quot;w-32 px-4 py-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-4 focus:ring-orange-100 focus:border-orange-500 transition&quot;
                  placeholder=&quot;0&quot;
                /&gt;
              &lt;/div&gt;
            &lt;/section&gt;
          &lt;/div&gt;

          {/* Preview Panel */}
          &lt;div className=&quot;lg:sticky lg:top-24 lg:h-screen lg:overflow-y-auto space-y-8&quot;&gt;
            &lt;div className=&quot;bg-white rounded-2xl shadow-lg border border-gray-200 p-8&quot;&gt;
              &lt;h3 className=&quot;text-xl font-bold text-gray-900 mb-6 text-center&quot;&gt;Premium Preview&lt;/h3&gt;
              &lt;div className=&quot;space-y-4 mb-8&quot;&gt;
                {preview.propertyPremium &gt; 0 &amp;&amp; (
                  &lt;div className=&quot;flex justify-between py-3 border-b border-gray-200&quot;&gt;
                    &lt;span className=&quot;text-lg font-semibold text-gray-700&quot;&gt;Property&lt;/span&gt;
                    &lt;span className=&quot;text-2xl font-bold text-green-600&quot;&gt;${preview.propertyPremium.toLocaleString()}&lt;/span&gt;
                  &lt;/div&gt;
                )}
                {preview.glPremium &gt; 0 &amp;&amp; (
                  &lt;div className=&quot;flex justify-between py-3 border-b border-gray-200&quot;&gt;
                    &lt;span className=&quot;text-lg font-semibold text-gray-700&quot;&gt;General Liability&lt;/span&gt;
                    &lt;span className=&quot;text-2xl font-bold text-blue-600&quot;&gt;${preview.glPremium.toLocaleString()}&lt;/span&gt;
                  &lt;/div&gt;
                )}
                &lt;div className=&quot;flex justify-between py-4 bg-gradient-to-r from-gray-50 to-gray-100 rounded-xl p-4 border&quot;&gt;
                  &lt;span className=&quot;text-2xl font-bold text-gray-900&quot;&gt;Total Premium&lt;/span&gt;
                  &lt;span className=&quot;text-3xl font-bold bg-gradient-to-r from-indigo-500 to-purple-600 bg-clip-text text-transparent&quot;&gt;${preview.totalPremium.toLocaleString()}&lt;/span&gt;
                &lt;/div&gt;
              &lt;/div&gt;
              &lt;div className=&quot;space-y-3&quot;&gt;
                &lt;button
                  onClick={saveDraft}
                  className=&quot;w-full bg-green-500 hover:bg-green-600 text-white font-bold py-4 px-6 rounded-xl shadow-lg focus:outline-none focus:ring-4 focus:ring-green-200 transition-all text-lg&quot;
                  disabled={preview.totalPremium === 0}
                &gt;
                  💾 Save Draft
                &lt;/button&gt;
                &lt;button
                  onClick={generatePDF}
                  className=&quot;w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white font-bold py-4 px-6 rounded-xl shadow-lg focus:outline-none focus:ring-4 focus:ring-indigo-200 transition-all text-lg&quot;
                  disabled={preview.totalPremium === 0}
                &gt;
                  📄 Generate &amp; Download PDF
                &lt;/button&gt;
                &lt;button
                  onClick={() =&gt; navigate('/')}
                  className=&quot;w-full bg-gray-500 hover:bg-gray-600 text-white font-bold py-4 px-6 rounded-xl shadow-lg focus:outline-none focus:ring-4 focus:ring-gray-200 transition-all text-lg&quot;
                &gt;
                  ← Back to Dashboard
                &lt;/button&gt;
              &lt;/div&gt;
            &lt;/div&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/div&gt;
    &lt;/&gt;
  );
};

export default QuoteForm;

